import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Index-Operator.md","filePath":"manual-zh/Matrix-Index-Operator.md","lastUpdated":1785684581000}'),h={name:"manual-zh/Matrix-Index-Operator.md"};function o(n,t,b,i,p,l){return e(),a("div",null,[...t[0]||(t[0]=[r('<h4 id="_16-4-1-3-索引运算符" tabindex="-1">16.4.1.3 索引运算符 <code>()</code> <a class="header-anchor" href="#_16-4-1-3-索引运算符" aria-label="Permalink to &quot;16.4.1.3 索引运算符 `()`&quot;">​</a></h4><p>子矩阵或索引运算符写作 <code>m(rindex, cindex)</code>，其结果包含 m 中行索引由向量 rindex 给出、列索引由向量 cindex 给出的行与列。</p><p>在最简单的情况下，如果 rindex 和 cindex 都是标量，则结果也是一个标量：</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(1, 1)</th><th>⇒</th><th>10</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(1, 2)</td><td>⇒</td><td>20</td></tr><tr><td>{10, 20; 30, 40}(2, 1)</td><td>⇒</td><td>30</td></tr><tr><td>{10, 20; 30, 40}(2, 2)</td><td>⇒</td><td>40</td></tr></tbody></table><p>如果索引参数有多个元素，则结果包含多行或多列：</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(1:2, 1)</th><th>⇒</th><th>{10; 30}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, 1:2)</td><td>⇒</td><td>{30, 40}</td></tr><tr><td>{10, 20; 30, 40}(1:2, 1:2)</td><td>⇒</td><td>{10, 20; 30, 40}</td></tr></tbody></table><p>特殊参数 “:” 可以代表被索引矩阵中的所有行或列，如下所示：</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}(:, 1)</th><th>⇒</th><th>{10; 30}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, 😃</td><td>⇒</td><td>{30, 40}</td></tr><tr><td>{10, 20; 30, 40}(:, 😃</td><td>⇒</td><td>{10, 20; 30, 40}</td></tr></tbody></table><p>索引参数不必有序，也可以包含重复值，如下所示：</p><table tabindex="0"><thead><tr><th>{10, 20; 30, 40}({2, 1}, 1)</th><th>⇒</th><th>{30; 10}</th></tr></thead><tbody><tr><td>{10, 20; 30, 40}(2, {2; 2; 1})</td><td>⇒</td><td>{40, 40, 30}</td></tr><tr><td>{10, 20; 30, 40}(2:1:-1, 😃</td><td>⇒</td><td>{30, 40; 10, 20}</td></tr></tbody></table><p>当被索引的矩阵是行或列向量时，只需要一个索引参数，如下所示：</p><table tabindex="0"><thead><tr><th>{11, 12, 13, 14, 15}(2:4)</th><th>⇒</th><th>{12, 13, 14}</th></tr></thead><tbody><tr><td>{11; 12; 13; 14; 15}(2:4)</td><td>⇒</td><td>{12; 13; 14}</td></tr></tbody></table><p>当索引不是整数时，PSPP 会丢弃其小数部分。索引小于 1 或大于行数或列数时出错：</p><table tabindex="0"><thead><tr><th>{11, 12, 13, 14}({2.5, 4.6})</th><th>⇒</th><th>{12, 14}</th></tr></thead><tbody><tr><td>{11; 12; 13; 14}(0)</td><td>⇒</td><td>(错误)</td></tr></tbody></table>',14)])])}const c=d(h,[["render",o]]);export{_ as __pageData,c as default};
